namespace FiveSmartFarmCreators.Ichu.Platform.OperationsMonitoring.Interfaces.Rest.Resources;

/// <summary>
///     Resource representing a field event (HealthEvent, Birth) or clinical intervention (Vaccination, Treatment,
///     Insemination). The client generates the operation identifier once and reuses it on every retry.
/// </summary>
/// <param name="OperationId">The identifier generated by the client.</param>
/// <param name="AnimalId">The animal the operation was applied to.</param>
/// <param name="Type">The kind of operation.</param>
/// <param name="OccurredAt">The instant the operation happened.</param>
/// <param name="Observation">A free-text observation.</param>
/// <param name="Product">The administered product, only for clinical interventions.</param>
/// <param name="Dose">The administered dose, only for clinical interventions.</param>
public record RegisterLivestockOperationResource(
    Guid OperationId,
    Guid? AnimalId,
    string? Type,
    DateTimeOffset? OccurredAt,
    string? Observation,
    string? Product,
    string? Dose);
